SELECT  FROM metal_material r WHERE r.del_flag='0' AND r.factory_id IS NOT NULL AND r.factory_id=#{factoryId} AND r.material_code LIKE #{q.codePattern} ESCAPE '!'
AND r.metal_type_id=#{q.metalTypeId}
AND r.material_type =#{q.materialType}
AND r.specification LIKE #{q.specificationPattern} ESCAPE '!'
AND r.create_time >=#{q.startTime}AND r.create_time <#{q.endExclusive} AND r.factory_id=#{q.factoryId} ORDER BY r.material_id ASC
